async function resolveBoardSquare(type){if(type==='battle'){beginMobBattle();battle.boardBattle=true;battle.boardKind='battle';return}if(type==='mini'){beginBoardMini();return}if(type==='boss'){startBoardBoss();return}const s=stats();if(type==='damage'){const damage=Math.max(3,Math.round(s.maxHp*(state.board?0.24:0.16)));state.hp=Math.max(1,state.hp-damage);showBoardMap(`💥 落とし穴！ HPが ${damage}減った！`);beep(110,.18);return}if(type==='heal'){const hpBefore=state.hp,mpBefore=state.mp;state.hp=Math.min(s.maxHp,state.hp+Math.round(s.maxHp*.45));state.mp=Math.min(s.maxMp,state.mp+Math.round(s.maxMp*.35));showBoardMap(`💚 いやしの泉！ HP＋${state.hp-hpBefore}、MP＋${state.mp-mpBefore}！`);beep(720,.18);return}if(type==='xp'){const amount=xpForBoardLevels(state.board?9:2),levels=addExp(amount),newStats=stats();if(levels){state.hp=newStats.maxHp;state.mp=newStats.maxMp;state.waters=3}showBoardMap(`⭐ 経験値 ${amount}！ レベルが ${levels}上がった！`);beep(900,.2);return}showBoardMap()}
