function showPathMap(custom){normalizePathState();playMusic('map');show('#mapScreen');const map=pathMaps[state.board],node=map.nodes[state.boardNode],s=stats(),remaining=map.total-node.d;renderPathNodes();$('#mapBackdrop').classList.toggle('final-map',state.board===1);$('#mapLevel').textContent=`${state.level}/${MAX_LEVEL}`;$('#mapHp').textContent=`${state.hp}/${s.maxHp}`;$('#mapCarrots').textContent=state.carrots;$('#chapterLabel').textContent=map.chapter;$('#locationName').textContent=map.name;$('#mapMessage').textContent=custom||`${map.boss==='mayu'?'中ボス・まゆ':'大ボス・こうき'}へ向かって、1マスずつ進もう！`;$('#goalDistance').textContent=remaining?`ボスまで あと${remaining}マス`:'ボスマスに到着！';$('#advanceBtn').textContent=remaining?'ルーレットを回す！':'ボスへの挑戦を選ぶ';$('#advanceBtn').disabled=false;rouletteBusy=false;save()}
showMap=showPathMap;
function openRouteChoice(){return new Promise(resolve=>{$('#choiceKicker').textContent='ROUTE SELECT';$('#choiceTitle').textContent='どちらへ進む？';$('#choiceText').textContent='上は回復・経験値が多め。下は戦闘・危険マスが多め！';$('#routeChoices').classList.remove('hidden');$('#bossChoices').classList.add('hidden');$('#mapChoice').classList.remove('hidden');$('#upperRouteBtn').onclick=()=>{$('#mapChoice').classList.add('hidden');resolve('u')};$('#lowerRouteBtn').onclick=()=>{$('#mapChoice').classList.add('hidden');resolve('l')}})}
function openBossChoice(){const map=pathMaps[state.board];$('#choiceKicker').textContent='BOSS SQUARE';$('#choiceTitle').textContent=`${map.boss==='mayu'?'まゆ':'こうき'}のマスに到着！`;$('#choiceText').textContent='今すぐ戦う？ それともスタートへ戻ってレベルを上げる？';$('#routeChoices').classList.add('hidden');$('#bossChoices').classList.remove('hidden');$('#mapChoice').classList.remove('hidden');$('#fightBossBtn').onclick=()=>{$('#mapChoice').classList.add('hidden');startPathBoss()};$('#returnStartBtn').onclick=()=>{$('#mapChoice').classList.add('hidden');state.boardNode=map.start;state.boardPos=0;delete state.pendingNext;showPathMap('レベルと持ち物を保ったまま、スタートへ戻った！')}}
function chooseNextNode(map,node,lane){if(node.next.length<2)return node.next[0];return node.next.find(id=>id.endsWith(lane))||node.next[0]}
async function rollPathRoulette(){if(rouletteBusy)return;normalizePathState();const map=pathMaps[state.board],startNode=map.nodes[state.boardNode],remaining=map.total-startNode.d;if(!remaining){openBossChoice();return}rouletteBusy=true;$('#advanceBtn').disabled=true;const display=$('#rouletteNumber');display.classList.add('spinning');let result=1;for(let i=0;i<13;i++){result=1+Math.floor(Math.random()*6);display.textContent=result;beep(300+i*24,.035);await wait(65+i*5)}display.classList.remove('spinning');if(result>remaining){rouletteBusy=false;$('#advanceBtn').disabled=false;$('#mapMessage').textContent=`${result}！ ボスまであと${remaining}マス。ぴったりではないので、その場にとどまった！`;beep(145,.18);return}for(let step=0;step<result;step++){let node=map.nodes[state.boardNode],next;if(node.next.length>1){let lane=state.pendingNext;if(!lane)lane=await openRouteChoice();next=chooseNextNode(map,node,lane);delete state.pendingNext}else next=node.next[0];state.boardNode=next;state.boardPos=map.nodes[next].d;renderPathNodes(true);beep(420+step*25,.05);await wait(430)}renderPathNodes(false);save();const landed=map.nodes[state.boardNode];if(landed.type==='branch'){state.pendingNext=await openRouteChoice();showPathMap(`${state.pendingNext==='u'?'上':'下'}の道を選んだ！ 次のルーレットで進もう！`);return}await resolvePathSquare(landed.type)}
async function resolvePathSquare(type){if(type==='battle'){beginMobBattle();battle.boardBattle=true;battle.pathBoard=true;battle.boardKind='battle';return}if(type==='mini'){beginPathMini();return}if(type==='boss'){openBossChoice();return}const s=stats();if(type==='damage'){const damage=Math.max(3,Math.round(s.maxHp*(state.board?.24:.16)));state.hp=Math.max(1,state.hp-damage);showPathMap(`💥 危険なマス！ HPが ${damage}減った！`);beep(110,.18);return}if(type==='heal'){const beforeHp=state.hp,beforeMp=state.mp;state.hp=Math.min(s.maxHp,state.hp+Math.round(s.maxHp*.45));state.mp=Math.min(s.maxMp,state.mp+Math.round(s.maxMp*.35));showPathMap(`💚 回復マス！ HP＋${state.hp-beforeHp}、MP＋${state.mp-beforeMp}！`);beep(720,.18);return}if(type==='xp'){const amount=xpForBoardLevels(state.board?7:2),levels=addExp(amount),nextStats=stats();if(levels){state.hp=nextStats.maxHp;state.mp=nextStats.maxMp;state.waters=3}showPathMap(`⭐ 経験値 ${amount}！ レベルが ${levels}上がった！`);beep(900,.2);return}showPathMap()}
function beginPathMini(){const index=state.board?5:0,m=miniBosses[index],lv=Math.min(MAX_LEVEL,state.level+2),maxHp=55+lv*8;battle={enemies:[{name:m.name,icon:m.icon,lv,maxHp,currentHp:maxHp,atk:6+lv*.95,spd:5+lv*1.25,xp:40+lv*10,id:0}],boss:false,miniBoss:true,boardBattle:true,pathBoard:true,boardKind:'mini',lost:false,guard:false};startBattle(`小ボス・${m.name}が あらわれた！`)}
function startPathBoss(){const map=pathMaps[state.board];beginBoss(map.boss);battle.boardBattle=true;battle.pathBoard=true;battle.boardKind='boss'}
function pathWin(){playMusic('victory',true);battle.lost=false;const xp=battle.enemies.reduce((sum,e)=>sum+e.xp,0),levels=addExp(xp),newStats=stats();state.totalWins++;state.score+=xp*10+Math.max(0,state.hp)*3;if(levels){state.hp=newStats.maxHp;state.mp=newStats.maxMp;state.waters=3;state.carrots=Math.min(5,state.carrots+1)}else state.mp=Math.min(newStats.maxMp,state.mp+4);if(battle.boardKind==='boss'){if(battle.boss==='mayu'){state.board=1;state.boardNode=pathMaps[1].start;state.boardPos=0;state.stage=5;state.carrots=5;state.pendingMapMessage='まゆを倒した！ こうきへ続く最終マップが現れた！'}else state.finished=true}else state.pendingMapMessage=battle.boardKind==='mini'?'小ボスを撃破！ 止まったマスから再開！':'敵を倒した！ 止まったマスから再開！';save();show('#resultScreen');$('#resultKicker').textContent=battle.boardKind==='boss'?'BOSS DEFEATED!':battle.boardKind==='mini'?'MINI BOSS DEFEATED!':'VICTORY!';$('#resultIcon').textContent=battle.boardKind==='boss'?'👑':battle.boardKind==='mini'?'🐾':'🏆';$('#resultTitle').textContent=battle.boss==='mayu'?'まゆに勝った！':battle.boss==='kouki'?'こうきを倒した！':`${battle.enemies.length}体を倒した！`;$('#resultText').innerHTML=`経験値 <b>${xp}</b> を てにいれた！<br>たるとは レベル${state.level}。${levels?'<br>お水の回数が3回に戻った！':''}`;$('#levelUp').classList.toggle('hidden',!levels);$('#levelUp').textContent=levels?`LEVEL UP!　${levels>1?'×'+levels:''}`:'LEVEL UP!';$('#resultBtn').textContent=state.finished?'エンディングへ':'すごろくへ戻る';beep(880,.18)}
const winBeforePath=win;
win=function(){if(battle&&battle.pathBoard)return pathWin();return winBeforePath()};
function pathAfterResult(){if(!battle||!battle.pathBoard)return boardAfterResult();if(battle.lost){state=fresh();showPathMap('勇者たるとの冒険が、もう一度はじまる！');return}if(state.finished){ending();return}const message=state.pendingMapMessage;delete state.pendingMapMessage;showPathMap(message)}
$('#advanceBtn').onclick=rollPathRoulette;
$('#resultBtn').onclick=pathAfterResult;

function createRouteMapV2(name,chapter,boss,stage,hard=false){const base=[
  ['s',0,70,260,'start',['m1']],['m1',1,200,260,'battle',['m2']],['m2',2,330,260,'heal',['f1']],['f1',3,460,260,'branch',['t1','b1']],
  ['t1',4,590,150,hard?'battle':'xp',['t2']],['t2',5,720,85,'battle',['t3']],['t3',6,850,75,'heal',['t4']],['t4',7,980,105,'mini',['t5']],['t5',8,1110,150,'xp',['t6']],['t6',9,1240,205,'battle',['merge']],
  ['b1',4,590,360,'battle',['b2']],['b2',5,720,425,'damage',['f2']],['f2',6,850,390,'branch',['u1','l1']],
  ['u1',7,980,320,'heal',['u2']],['u2',8,1110,310,'xp',['u3']],['u3',9,1240,235,'battle',['merge']],
  ['l1',7,980,470,'damage',['l2']],['l2',8,1110,455,hard?'mini':'battle',['l3']],['l3',9,1240,350,'xp',['merge']],
  ['merge',10,1370,260,'heal',['e1']],['e1',11,1500,260,'mini',['e2']],['e2',12,1630,260,'battle',['boss']],['boss',13,1770,260,'boss',[]]
];const nodes=Object.fromEntries(base.map(([id,d,x,y,type,next])=>[id,{id,d,x,y,type,next}]));if(hard){nodes.m2.type='xp';nodes.t3.type='battle';nodes.merge.type='xp';nodes.u1.type='battle'}return{name,chapter,boss,stage,total:13,start:'s',nodes,width:1860}}
const routeMapsV2=[createRouteMapV2('まゆへの冒険ロード','MAP 1・MAYU ROUTE','mayu',0),createRouteMapV2('こうきの最終試験ロード','MAP 2・KOUKI ROUTE','kouki',5,true)];
function normalizeRouteV2(){if(!Number.isFinite(state.board))state.board=0;state.board=Math.min(1,state.board);const map=routeMapsV2[state.board];if(!state.routeNode||!map.nodes[state.routeNode])state.routeNode=map.start;state.stage=map.stage;state.boardPos=map.nodes[state.routeNode].d}
function renderRouteV2(walking=false){normalizeRouteV2();const map=routeMapsV2[state.board],wrap=$('#mapNodes'),scale=innerHeight<720?.75:1;wrap.className='map-nodes route-board-v2';wrap.style.width=`${map.width}px`;wrap.innerHTML='';const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','route-svg');svg.setAttribute('viewBox',`0 0 ${map.width} ${520*scale}`);Object.values(map.nodes).forEach(node=>node.next.forEach(id=>{const next=map.nodes[id],line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',node.x);line.setAttribute('y1',node.y*scale);line.setAttribute('x2',next.x);line.setAttribute('y2',next.y*scale);svg.appendChild(line)}));wrap.appendChild(svg);[['上ルート：回復・経験値多め',760,25],['下ルート：戦闘・危険多め',720,495]].forEach(([textValue,x,y])=>{const label=document.createElement('span');label.className='route-label';label.textContent=textValue;label.style.left=`${x}px`;label.style.top=`${y*scale}px`;wrap.appendChild(label)});const current=map.nodes[state.routeNode];Object.values(map.nodes).forEach(node=>{const info=squareInfo[node.type]||['🔀','分岐'],el=document.createElement('span');el.className=`map-node ${node.type}${node.id===state.routeNode?' current':''}${node.d<current.d?' visited':''}`;el.style.left=`${node.x}px`;el.style.top=`${node.y*scale}px`;el.innerHTML=`<b>${info[0]}</b><small>${node.d}</small>`;el.setAttribute('aria-label',`${node.d}マス目 ${info[1]}`);if(node.id===state.routeNode){const token=document.createElement('img');token.className=`board-token${walking?' walking':''}`;token.src='assets/taruto-card-v1.png';token.alt='現在地・たると';el.appendChild(token)}wrap.appendChild(el)});requestAnimationFrame(()=>{const currentElement=wrap.querySelector('.current');if(currentElement)currentElement.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'})})}
function showRouteMapV2(custom){normalizeRouteV2();playMusic('map');show('#mapScreen');const map=routeMapsV2[state.board],node=map.nodes[state.routeNode],s=stats(),remaining=map.total-node.d;renderRouteV2();$('#mapBackdrop').classList.toggle('final-map',state.board===1);$('#mapLevel').textContent=`${state.level}/${MAX_LEVEL}`;$('#mapHp').textContent=`${state.hp}/${s.maxHp}`;$('#mapCarrots').textContent=state.carrots;$('#chapterLabel').textContent=map.chapter;$('#locationName').textContent=map.name;$('#mapMessage').textContent=custom||'道は線でつながっている。分岐で好きなルートを選ぼう！';$('#goalDistance').textContent=remaining?`ボスまで あと${remaining}マス`:'ボスマスに到着！';$('#advanceBtn').textContent=remaining?'ルーレットを回す！':'ボスへの挑戦を選ぶ';$('#advanceBtn').disabled=false;rouletteBusy=false;save()}
showMap=showRouteMapV2;
function askRouteV2(node){return new Promise(resolve=>{$('#choiceKicker').textContent='ROUTE SELECT';$('#choiceTitle').textContent='進む道を選ぼう！';$('#choiceText').textContent=node.id==='f1'?'上は回復・経験値多め。下は戦闘・危険多め！':'内側は回復ルート。外側は危険だが経験値も狙える！';$('#routeChoices').classList.remove('hidden');$('#bossChoices').classList.add('hidden');$('#upperRouteBtn').textContent=node.id==='f1'?'🌤 上ルート':'💚 内側ルート';$('#lowerRouteBtn').textContent=node.id==='f1'?'🌲 下ルート':'🔥 外側ルート';$('#mapChoice').classList.remove('hidden');$('#upperRouteBtn').onclick=()=>{$('#mapChoice').classList.add('hidden');resolve(node.next[0])};$('#lowerRouteBtn').onclick=()=>{$('#mapChoice').classList.add('hidden');resolve(node.next[1])}})}
function askBossV2(){const map=routeMapsV2[state.board];$('#choiceKicker').textContent='BOSS SQUARE';$('#choiceTitle').textContent=`${map.boss==='mayu'?'まゆ':'こうき'}のマスに到着！`;$('#choiceText').textContent='戦うか、スタートへ戻ってレベルを上げるか選ぼう！';$('#routeChoices').classList.add('hidden');$('#bossChoices').classList.remove('hidden');$('#mapChoice').classList.remove('hidden');$('#fightBossBtn').onclick=()=>{$('#mapChoice').classList.add('hidden');startBossV2()};$('#returnStartBtn').onclick=()=>{$('#mapChoice').classList.add('hidden');state.routeNode=map.start;state.boardPos=0;delete state.routeNext;showRouteMapV2('レベルと持ち物を保ったまま、スタートへ戻った！')}}
async function rollRouteV2(){if(rouletteBusy)return;normalizeRouteV2();const map=routeMapsV2[state.board],current=map.nodes[state.routeNode],remaining=map.total-current.d;if(!remaining){askBossV2();return}rouletteBusy=true;$('#advanceBtn').disabled=true;const display=$('#rouletteNumber');display.classList.add('spinning');let result=1;for(let i=0;i<13;i++){result=1+Math.floor(Math.random()*6);display.textContent=result;beep(300+i*24,.035);await wait(65+i*5)}display.classList.remove('spinning');if(result>remaining){rouletteBusy=false;$('#advanceBtn').disabled=false;$('#mapMessage').textContent=`${result}！ ボスまであと${remaining}マス。ぴったりではないので進まない！`;beep(145,.18);return}for(let step=0;step<result;step++){const node=map.nodes[state.routeNode];let next;if(node.next.length>1){next=state.routeNext||await askRouteV2(node);delete state.routeNext}else next=node.next[0];state.routeNode=next;state.boardPos=map.nodes[next].d;renderRouteV2(true);beep(420+step*25,.05);await wait(440)}renderRouteV2(false);save();const landed=map.nodes[state.routeNode];if(landed.type==='branch'){state.routeNext=await askRouteV2(landed);showRouteMapV2('進むルートを決めた！ 次のルーレットで出発！');return}await resolveRouteV2Square(landed.type)}
async function resolveRouteV2Square(type){if(type==='battle'){beginMobBattle();battle.boardBattle=true;battle.routeV2=true;battle.boardKind='battle';return}if(type==='mini'){beginRouteV2Mini();return}if(type==='boss'){askBossV2();return}const s=stats();if(type==='damage'){const damage=Math.max(3,Math.round(s.maxHp*(state.board?.24:.16)));state.hp=Math.max(1,state.hp-damage);showRouteMapV2(`💥 ダメージマス！ HPが ${damage}減った！`);beep(110,.18);return}if(type==='heal'){const hpBefore=state.hp,mpBefore=state.mp;state.hp=Math.min(s.maxHp,state.hp+Math.round(s.maxHp*.45));state.mp=Math.min(s.maxMp,state.mp+Math.round(s.maxMp*.35));showRouteMapV2(`💚 回復マス！ HP＋${state.hp-hpBefore}、MP＋${state.mp-mpBefore}！`);beep(720,.18);return}if(type==='xp'){const amount=xpForBoardLevels(state.board?7:2),levels=addExp(amount),nextStats=stats();if(levels){state.hp=nextStats.maxHp;state.mp=nextStats.maxMp;state.waters=3}showRouteMapV2(`⭐ 経験値 ${amount}！ レベルが ${levels}上がった！`);beep(900,.2);return}showRouteMapV2()}
