function routeV2Win(){playMusic('victory',true);battle.lost=false;const xp=battle.enemies.reduce((sum,e)=>sum+e.xp,0),levels=addExp(xp),newStats=stats();state.totalWins++;state.score+=xp*10+Math.max(0,state.hp)*3;if(levels){state.hp=newStats.maxHp;state.mp=newStats.maxMp;state.waters=3;state.carrots=Math.min(5,state.carrots+1)}else state.mp=Math.min(newStats.maxMp,state.mp+4);if(battle.boardKind==='boss'){if(battle.boss==='mayu'){state.board=1;state.routeNode=routeMapsV2[1].start;state.boardPos=0;state.stage=5;state.carrots=5;state.pendingMapMessage='まゆを倒した！ こうきへ続く新しいマップが現れた！'}else state.finished=true}else state.pendingMapMessage=battle.boardKind==='mini'?'小ボスを撃破！ このマスから再開！':'敵を倒した！ このマスから再開！';save();show('#resultScreen');$('#resultKicker').textContent=battle.boardKind==='boss'?'BOSS DEFEATED!':battle.boardKind==='mini'?'MINI BOSS DEFEATED!':'VICTORY!';$('#resultIcon').textContent=battle.boardKind==='boss'?'👑':battle.boardKind==='mini'?'🐾':'🏆';$('#resultTitle').textContent=battle.boss==='mayu'?'まゆに勝った！':battle.boss==='kouki'?'こうきを倒した！':`${battle.enemies.length}体を倒した！`;$('#resultText').innerHTML=`経験値 <b>${xp}</b> を てにいれた！<br>たるとは レベル${state.level}。${levels?'<br>お水の回数が3回に戻った！':''}`;$('#levelUp').classList.toggle('hidden',!levels);$('#levelUp').textContent=levels?`LEVEL UP!　${levels>1?'×'+levels:''}`:'LEVEL UP!';$('#resultBtn').textContent=state.finished?'エンディングへ':'すごろくへ戻る';beep(880,.18)}
