function renderRouteV3(){normalizeRouteV2();const map=routeMapsV2[state.board],wrap=$('#mapNodes'),scale=innerHeight<720?.75:1,current=map.nodes[state.routeNode];wrap.className='map-nodes route-board-v2';wrap.style.width=`${map.width}px`;wrap.innerHTML='';const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','route-svg');svg.setAttribute('viewBox',`0 0 ${map.width} ${520*scale}`);Object.values(map.nodes).forEach(node=>node.next.forEach(id=>{const next=map.nodes[id],line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',node.x);line.setAttribute('y1',node.y*scale);line.setAttribute('x2',next.x);line.setAttribute('y2',next.y*scale);svg.appendChild(line)}));wrap.appendChild(svg);Object.values(map.nodes).forEach(node=>{const info=squareInfo[node.type]||['🔀','分岐'],el=document.createElement('span');el.className=`map-node ${node.type}${node.id===state.routeNode?' current':''}${node.d<current.d?' visited':''}`;el.dataset.node=node.id;el.style.left=`${node.x}px`;el.style.top=`${node.y*scale}px`;el.innerHTML=`<b>${info[0]}</b><em>${routeSpaceLabels[node.type]}</em><small>${node.d}</small>`;el.setAttribute('aria-label',`${node.d}マス目 ${routeSpaceLabels[node.type]}`);wrap.appendChild(el)});const token=document.createElement('img');token.id='routeToken';token.className='route-token-v3';token.src='assets/taruto-card-v1.png';token.alt='たるとの現在地';token.style.left=`${current.x}px`;token.style.top=`${current.y*scale}px`;wrap.appendChild(token);setTimeout(()=>centerRouteNodeV3(state.routeNode,false),30)}
function centerRouteNodeV3(id,smooth=true){const map=routeMapsV2[state.board],node=map.nodes[id],viewport=$('#mapBackdrop');if(!node||!viewport)return;viewport.scrollTo({left:Math.max(0,node.x-viewport.clientWidth/2),behavior:smooth?'smooth':'auto'})}
