// Version 4.2: scrolling hex-field sugoroku
const HEX_COLS=14,HEX_ROWS=5,HEX_COUNT=HEX_COLS*HEX_ROWS;
const hexLabels={normal:['・','通常'],xp:['⭐','経験値'],heal:['💚','回復'],spawn:['🐾','小ボス'],mountain:['⛰️','山'],start:['🏠','START'],boss:['👑','BOSS']};
function hexId(col,row){return col*HEX_ROWS+row}
function hexCell(id){return hexMaps[state.board].cells[id]}
function seededShuffle(list,seed){let n=seed>>>0;for(let i=list.length-1;i>0;i--){n=(n*1664525+1013904223)>>>0;const j=n%(i+1);[list[i],list[j]]=[list[j],list[i]]}return list}
function buildHexMap(board,seed=9271){const cells=[];for(let col=0;col<HEX_COLS;col++)for(let row=0;row<HEX_ROWS;row++){const id=hexId(col,row);cells.push({id,col,row,type:'normal',x:52+col*55,y:38+row*51+(col%2?25:0)})}const available=seededShuffle(cells.filter(c=>c.col>1&&c.col<HEX_COLS-2).map(c=>c.id),seed+board*331),take=(count,type,filter=()=>true)=>{let used=0;for(const id of available){if(used>=count)break;if(cells[id].type==='normal'&&filter(cells[id])){cells[id].type=type;used++}}};take(7,'xp');take(7,'heal');const mountainCols={};take(7,'mountain',cell=>(mountainCols[cell.col]||0)<2&&(mountainCols[cell.col]=(mountainCols[cell.col]||0)+1));take(4,'spawn');cells[0].type='start';cells[HEX_COUNT-1].type='boss';return{cells,width:52+(HEX_COLS-1)*55+52,name:board?'こうきの最終試験場':'まゆの草原ヘックス',chapter:board?'MAP 2・KOUKI HEX FIELD':'MAP 1・MAYU HEX FIELD',boss:board?'kouki':'mayu'}}
let hexMaps=[buildHexMap(0),buildHexMap(1)];
function hexNeighbors(id){const c=hexCell(id),dirs=c.col%2?[[1,0],[-1,0],[0,1],[0,-1],[1,1],[-1,1]]:[[1,0],[-1,0],[0,1],[0,-1],[1,-1],[-1,-1]];return dirs.map(([dc,dr])=>{const col=c.col+dc,row=c.row+dr;return col>=0&&col<HEX_COLS&&row>=0&&row<HEX_ROWS?hexId(col,row):-1}).filter(x=>x>=0)}
function hexRoute(){const route=[];for(let col=0;col<HEX_COLS;col++){const rows=[0,1,2,3,4];if(col%2)rows.reverse();rows.forEach(row=>route.push(hexId(col,row)))}return route}
const HEX_ROUTE=hexRoute();
function initialHexEnemies(board){const valid=HEX_ROUTE.filter(id=>id>8&&id<HEX_COUNT-6&&hexMaps[board].cells[id].type!=='mountain');const picks=seededShuffle(valid,(state.mapSeed||4441)+board*97).slice(0,8);return picks.map((cell,i)=>({id:`e${board}-${i}-${Date.now()}`,cell,icon:['🐺','🦅','🐍','🦊','👾'][i%5]}))}
function normalizeHexState(){state.board=Number.isFinite(state.board)?Math.min(1,state.board):0;state.stage=state.board?5:0;state.mapSeed=state.mapSeed||Math.floor(Math.random()*1e9);hexMaps=[buildHexMap(0,state.mapSeed),buildHexMap(1,state.mapSeed)];if(!state.hex||state.hex.board!==state.board){state.hex={board:state.board,player:0,turn:0,enemies:initialHexEnemies(state.board),defeated:0,consumed:[],movesLeft:0}}if(!Array.isArray(state.hex.enemies))state.hex.enemies=initialHexEnemies(state.board);if(!Array.isArray(state.hex.consumed))state.hex.consumed=[];state.hex.movesLeft=Number.isFinite(state.hex.movesLeft)?state.hex.movesLeft:0;state.hex.player=Math.max(0,Math.min(HEX_COUNT-1,state.hex.player||0));state.hex.turn=state.hex.turn||0}
function renderHexMap(){normalizeHexState();const map=hexMaps[state.board],wrap=$('#mapNodes'),current=hexCell(state.hex.player),reachable=new Set(state.hex.movesLeft>0?hexNeighbors(state.hex.player).filter(id=>hexCell(id).type!=='mountain'):[]);wrap.className='map-nodes hex-board';wrap.style.width=`${map.width}px`;wrap.innerHTML='';map.cells.forEach(cell=>{const type=state.hex.consumed.includes(cell.id)?'normal':cell.type,info=hexLabels[type],canMove=reachable.has(cell.id),el=document.createElement('div');el.className=`hex-space ${type}${cell.id===state.hex.player?' current':canMove?' reachable':' blocked'}`;el.dataset.cell=cell.id;el.style.left=`${cell.x}px`;el.style.top=`${cell.y}px`;el.innerHTML=`<span class="hex-icon">${info[0]}</span><strong>${info[1]}</strong><small>${cell.id+1}</small>${type==='spawn'?'<i class="hex-spawner">✦</i>':''}`;if(canMove){el.setAttribute('role','button');el.setAttribute('tabindex','0');el.setAttribute('aria-label',`${info[1]}マスへ移動`);el.onclick=()=>chooseHexMove(cell.id);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();chooseHexMove(cell.id)}}}wrap.appendChild(el)});state.hex.enemies.forEach(enemy=>{const cell=hexCell(enemy.cell),el=document.createElement('span');el.className='hex-enemy';el.dataset.enemy=enemy.id;el.style.left=`${cell.x}px`;el.style.top=`${cell.y}px`;el.textContent=enemy.icon;wrap.appendChild(el)});const token=document.createElement('img');token.id='hexToken';token.className='hex-token';token.src='assets/taruto-card-v1.png';token.alt='たると';token.style.left=`${current.x}px`;token.style.top=`${current.y}px`;wrap.appendChild(token);setTimeout(()=>centerHex(false),30)}
function centerHex(smooth=true){const cell=hexCell(state.hex.player),view=$('#mapBackdrop');view.scrollTo({left:Math.max(0,cell.x-view.clientWidth*.38),behavior:smooth?'smooth':'auto'})}
function showHexMap(custom){stopRouletteCycle();normalizeHexState();playMusic('map');show('#mapScreen');const screen=$('#mapScreen'),mustRoll=state.hex.movesLeft<=0;screen.classList.add('hex-mode');screen.classList.toggle('await-roll',mustRoll);renderHexMap();const map=hexMaps[state.board],s=stats(),boss=hexCell(state.hex.player).type==='boss';$('#mapBackdrop').classList.toggle('final-map',state.board===1);$('#mapLevel').textContent=`${state.level}/${MAX_LEVEL}`;$('#mapHp').textContent=`${state.hp}/${s.maxHp}`;$('#mapCarrots').textContent=state.carrots;$('#chapterLabel').textContent=map.chapter;$('#locationName').textContent=map.name;$('#mapMessage').textContent=custom||(mustRoll?'ルーレットをタップして、このターンの移動数を決めよう！':`あと${state.hex.movesLeft}マス。光る六角形をタッチ！`);$('#goalDistance').textContent=boss?'ボスマスに到着！':mustRoll?`ターン ${state.hex.turn+1}・敵 ${state.hex.enemies.length}体`:`残り ${state.hex.movesLeft}マス`;$('#rouletteNumber').textContent='?';rouletteBusy=false;hexMoveBusy=false;save();if(boss)setTimeout(askBossV2,250)}
showMap=showHexMap;
function hexNextOnRoute(){const index=HEX_ROUTE.indexOf(state.hex.player);return HEX_ROUTE[Math.min(HEX_ROUTE.length-1,index+1)]}
async function animateHexPlayer(next){state.hex.player=next;const cell=hexCell(next),token=$('#hexToken');if(token){token.classList.add('walking');token.style.left=`${cell.x}px`;token.style.top=`${cell.y}px`}$$('.hex-space').forEach((el,i)=>el.classList.toggle('current',i===next));centerHex(true);await wait(430);if(token)token.classList.remove('walking')}
function shortestEnemyStep(from,target){if(from===target)return from;const queue=[from],seen=new Set([from]),prev=new Map();while(queue.length){const at=queue.shift();for(const n of hexNeighbors(at)){if(seen.has(n)||hexCell(n).type==='mountain')continue;seen.add(n);prev.set(n,at);if(n===target){let step=n;while(prev.get(step)!==from)step=prev.get(step);return step}queue.push(n)}}return from}
async function moveHexEnemies(){for(const enemy of state.hex.enemies){enemy.cell=shortestEnemyStep(enemy.cell,state.hex.player);const cell=hexCell(enemy.cell),el=document.querySelector(`[data-enemy="${enemy.id}"]`);if(el){el.classList.add('moving');el.style.left=`${cell.x}px`;el.style.top=`${cell.y}px`}}await wait(430)}
function spawnHexEnemy(){const occupied=new Set(state.hex.enemies.map(e=>e.cell));const sources=hexMaps[state.board].cells.filter(c=>c.type!=='mountain'&&c.type!=='boss'&&!occupied.has(c.id)&&c.id!==state.hex.player);if(!sources.length)return false;const source=sources[Math.floor(Math.random()*sources.length)];state.hex.enemies.push({id:`spawn-${Date.now()}`,cell:source.id,icon:['🐺','🐍','🦅','👾'][Math.floor(Math.random()*4)]});return true}
function touchingHexEnemy(){return state.hex.enemies.find(e=>e.cell===state.hex.player)}
async function battleEntry(enemy){stopRouletteCycle();const overlay=document.createElement('div');overlay.className='battle-entry';overlay.innerHTML=`<span>ENCOUNTER!</span><b>${enemy.icon} 敵と接触！</b>`;document.body.appendChild(overlay);beep(120,.3);await wait(1000);overlay.remove();beginMobBattle();battle.boardBattle=true;battle.routeV2=true;battle.hexBattle=true;battle.hexEnemyId=enemy.id;battle.boardKind='battle'}
async function resolveHexLanding(){const enemy=touchingHexEnemy();if(enemy){await battleEntry(enemy);return}const cell=hexCell(state.hex.player),type=state.hex.consumed.includes(cell.id)?'normal':cell.type,s=stats();if(type==='boss'){askBossV2();return}if(type==='spawn'){state.hex.consumed.push(cell.id);beginAdaptiveMiniBoss();return}if(type==='heal'){const before=state.hp;state.hp=Math.min(s.maxHp,state.hp+Math.round(s.maxHp*.4));state.mp=Math.min(s.maxMp,state.mp+Math.round(s.maxMp*.25));state.hex.consumed.push(cell.id);showHexMap(`💚 回復マス！ HPが ${state.hp-before}回復。通常マスに変わった！`);return}if(type==='xp'){const amount=xpForBoardLevels(state.board?3:1),levels=addExp(amount),ns=stats();if(levels){state.hp=ns.maxHp;state.mp=ns.maxMp;state.waters=3}state.hex.consumed.push(cell.id);showHexMap(`⭐ 経験値 ${amount}を獲得！ 通常マスに変わった！`);return}showHexMap(state.hex.movesLeft>0?`あと${state.hex.movesLeft}マス移動できる！`:'敵も1マス動いた。次のターンへ！')}
async function advanceHex(result){normalizeHexState();if(hexCell(state.hex.player).type==='boss'){askBossV2();return}for(let i=0;i<result;i++){const next=hexNextOnRoute();if(next===state.hex.player)break;await animateHexPlayer(next);if(touchingHexEnemy()){await battleEntry(touchingHexEnemy());return}}state.hex.turn++;await moveHexEnemies();if(touchingHexEnemy()){await battleEntry(touchingHexEnemy());return}const spawned=Math.random()<.1&&spawnHexEnemy();if(spawned)$('#mapMessage').textContent='🌀 出現マスから新しい敵が湧き出した！';save();await resolveHexLanding()}
let hexMoveBusy=false;
async function chooseHexMove(destination){if(hexMoveBusy||state.hex.movesLeft<=0||!hexNeighbors(state.hex.player).includes(destination)||hexCell(destination).type==='mountain')return;hexMoveBusy=true;$$('.hex-space.reachable').forEach(el=>{el.classList.remove('reachable');el.classList.add('blocked')});const chosen=document.querySelector(`.hex-space[data-cell="${destination}"]`);if(chosen)chosen.classList.add('moving-to');await animateHexPlayer(destination);state.hex.movesLeft--;if(touchingHexEnemy()){await battleEntry(touchingHexEnemy());return}let spawned=false;if(state.hex.movesLeft<=0){state.hex.turn++;await moveHexEnemies();if(touchingHexEnemy()){await battleEntry(touchingHexEnemy());return}spawned=Math.random()<.18&&spawnHexEnemy()}save();await resolveHexLanding();if(spawned&&$('#mapScreen:not(.hidden)'))$('#mapMessage').textContent='敵が新しく出現した！'}
stopAndAdvanceRoulette=async function(){if(rouletteBusy||!rouletteCycleTimer)return;rouletteBusy=true;const trigger=$('#rouletteTrigger'),display=$('#rouletteNumber'),result=rouletteCycleValue;stopRouletteCycle();trigger.disabled=true;trigger.classList.add('confirmed');display.textContent=result;beep(920,.18);$('#mapMessage').textContent=`${result}で確定！`;await wait(700);trigger.classList.remove('confirmed');await advanceHex(result)};
$('#rouletteTrigger').onclick=()=>stopAndAdvanceRoulette();
const askBossBeforeHex=askBossV2;
askBossV2=function(){normalizeHexState();if(hexCell(state.hex.player).type!=='boss')return;askBossBeforeHex();const fight=$('#fightBossBtn');fight.onclick=()=>{$('#mapChoice').classList.add('hidden');startBossV2();battle.hexBattle=true};$('#returnStartBtn').onclick=()=>{$('#mapChoice').classList.add('hidden');state.hex.player=0;showHexMap('スタート地点へ戻った。レベルを上げて再挑戦しよう！')}};
const resultBeforeHex=$('#resultBtn').onclick;
$('#resultBtn').onclick=function(){if(!battle||!battle.hexBattle)return resultBeforeHex();if(battle.lost){state=fresh();showHexMap('倒れてしまった。レベル1から再スタート！');return}if(state.finished){ending();return}if(battle.hexEnemyId&&state.hex)state.hex.enemies=state.hex.enemies.filter(e=>e.id!==battle.hexEnemyId);if(battle.boardKind==='boss'&&battle.boss==='mayu'){state.mayuJoined=true;state.hex={board:1,player:0,turn:0,enemies:initialHexEnemies(1),defeated:0,consumed:[],movesLeft:0};state.pendingMapMessage='まゆが改心して仲間になった！ 次の戦いから一緒に参加する！'}showHexMap(state.pendingMapMessage||'敵を倒した！ 冒険を続けよう！');delete state.pendingMapMessage};

