addExp=function(amount){const before=state.level,levels=addExpBeforeV43(amount);if(levels&&pendingLevelDetails)pendingLevelDetails.unlocked=skillUnlockTable.filter(([,lv])=>lv>before&&lv<=state.level).map(([name])=>name);return levels};
const showLevelBeforeV43=showLevelStatus;
