const updateBattleBeforeV43=updateBattle;
updateBattle=function(){updateBattleBeforeV43();const buffs=[];if(battle.heroAtkBuffTurns>0)buffs.push(`⚔ 攻撃力 1.5倍・残り${battle.heroAtkBuffTurns}回`);if(battle.damageHalfTurns>0)buffs.push(`🛡 被ダメージ半減・残り${battle.damageHalfTurns}回`);$('#battleBuffs').classList.toggle('hidden',!buffs.length);$('#battleBuffs').textContent=buffs.join('　');if(battle.mayu){$('#mayuAllyHp').textContent=`HP ${Math.max(0,battle.mayu.hp)}/${battle.mayu.maxHp}`;$('#mayuAlly').classList.remove('hidden')}else $('#mayuAlly').classList.add('hidden')};
const startBattleBeforeV43=startBattle;
startBattle=function(text){if(state.mayuJoined&&battle.boss!=='mayu')battle.mayu={level:25,maxHp:150,hp:150,mp:60,atk:42,spd:44};startBattleBeforeV43(text);$('#enemySprite').classList.toggle('kouki-party',battle.boss==='kouki')};
async function mayuAutoAction(){const m=battle.mayu;if(!m||m.hp<=0||!aliveEnemies().length)return;const target=activeEnemy();if(state.hp<stats().maxHp*.38&&m.mp>=8){const heal=Math.round(stats().maxHp*.3);state.hp=Math.min(stats().maxHp,state.hp+heal);m.mp-=8;showNumber(heal,'heal');log(`まゆの「カフェラテ差し入れ」！\nたるとのHPが ${heal}回復！`)}else if(Math.random()<.25&&m.mp>=7){aliveEnemies().forEach(e=>e.attackDownTurns=Math.max(e.attackDownTurns||0,2));m.mp-=7;log('まゆの「女子大生トーク」！\n敵全体の攻撃力が低下！')}else{const dmg=Math.max(5,Math.round(m.atk*(.75+Math.random()*.25)));target.currentHp-=dmg;showNumber(dmg,'damage',target);hitEnemies(false);log(`まゆの「レポートラッシュ」！\n${target.name}に ${dmg}ダメージ！`)}updateBattle();await wait(520)}
const heroActionBeforeV43=heroAction;
heroAction=async function(type,s){if(type==='bite'){const target=activeEnemy();state.mp-=skills.bite.mp;const dmg=Math.max(3,Math.round(s.atk*(.85+Math.random()*.2)));target.currentHp-=dmg;target.bleedTurns=2;target.bleedPower=Math.max(1,Math.round(s.atk*.15));showNumber(dmg,'damage',target);hitEnemies(false);log(`たるとの かみつき！\n${target.name}に ${dmg}ダメージ＋弱い出血！`);updateBattle();await wait(560)}else if(type==='revive'){if(state.mp<15){log('友情の呼び声を使うMPが足りない！');await wait(350)}else if(!battle.mayu||battle.mayu.hp>0){log('いまは生き返らせる仲間がいない！');await wait(350)}else{state.mp-=15;battle.mayu.hp=Math.round(battle.mayu.maxHp*.5);log('たるとの「友情の呼び声」！\nまゆがHP半分で復活！');updateBattle();await wait(600)}}else await heroActionBeforeV43(type,s);if(battle.mayu&&battle.mayu.hp>0&&aliveEnemies().length)await mayuAutoAction()};
async function heroRevivalBanner(title,text){const banner=document.createElement('div');banner.className='revival-banner';banner.innerHTML=`<small>ONE MORE CHANCE</small><strong>${title}</strong><span>${text}</span>`;$('#battleScreen').appendChild(banner);beep(780,.35);await wait(1000);banner.remove()}
