function beginAdaptiveMiniBoss(){const lv=state.level,m=miniBosses[state.board?5:0],hp=50+lv*8;battle={enemies:[{name:m.name,icon:m.icon,lv,maxHp:hp,currentHp:hp,atk:5+lv*.9,spd:5+lv*1.05,xp:30+lv*8,id:0}],boss:false,miniBoss:true,boardBattle:true,routeV2:true,hexBattle:true,boardKind:'mini',lost:false,guard:false};startBattle(`出現マスから小ボス・${m.name}が現れた！`)}
